    ]


def multiply(a: list[list[float]], b: list[list[float]]) -> list[list[float]]:
    """Row-major 4x4 matrix product a * b."""
    return [
        [sum(a[row][k] * b[k][col] for k in range(4)) for col in range(4)]
        for row in range(4)
    ]


